"""Smoke test for the JSONL aggregator task. Does not reveal expected values."""

import json
import subprocess
import sys
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent


class AggregateSmokeTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        subprocess.run(
            [sys.executable, "aggregate.py"],
            cwd=HERE,
            check=True,
            timeout=180,
            capture_output=True,
            text=True,
        )
        cls.data = json.loads((HERE / "aggregates.json").read_text(encoding="utf-8"))

    def test_keys(self) -> None:
        self.assertIn("top_5_users_by_amount", self.data)
        self.assertIn("top_5_tags_by_count", self.data)

    def test_sizes(self) -> None:
        self.assertEqual(len(self.data["top_5_users_by_amount"]), 5)
        self.assertEqual(len(self.data["top_5_tags_by_count"]), 5)

    def test_types(self) -> None:
        for details in self.data["top_5_users_by_amount"].values():
            self.assertIsInstance(details["total_amount"], (int, float))
            self.assertIsInstance(details["total_items"], int)
        for details in self.data["top_5_tags_by_count"].values():
            self.assertIsInstance(details["count"], int)


if __name__ == "__main__":
    unittest.main()

