import json, collections, glob

def aggregate(records_glob):
    user_totals = collections.defaultdict(lambda: {'amount': 0.0, 'items': 0})
    tag_counts = collections.Counter()
    for file_path in sorted(glob.glob(records_glob)):
        with open(file_path, 'r') as f:
            for line in f:
                record = json.loads(line)
                user = record.get('user', 'unknown')
                user_totals[user]['amount'] += float(record.get('amount', 0))
                user_totals[user]['items'] += int(record.get('items', 0))
                for tag in record.get('tags', []):
                    tag_counts[tag] += 1

    user_list = [
        {'user': user, 'amount': round(data['amount'], 2), 'items': data['items']}
        for user, data in user_totals.items()
    ]
    user_list.sort(key=lambda x: (-x['amount'], x['user']))
    top_users = user_list[:5]

    tag_list = [
        {'tag': tag, 'count': count}
        for tag, count in tag_counts.items()
    ]
    tag_list.sort(key=lambda x: (-x['count'], x['tag']))
    top_tags = tag_list[:5]

    output = {
        'top_users': top_users,
        'top_tags': top_tags
    }
    with open('aggregates.json', 'w') as f:
        json.dump(output, f, indent=2)
    return 'aggregates.json'
